    private static void sortCasesMostSpecificFirst(List<FoldCase> cases, final ValueType enclosing) {
      Collections.sort(cases, new Comparator<FoldCase>() {
        @Override
        public int compare(FoldCase left, FoldCase right) {
          return Integer.compare(
              enclosing.getCases().knownSubtypesOf(right.type.typeAbstract().toString()).size(),
              enclosing.getCases().knownSubtypesOf(left.type.typeAbstract().toString()).size());
        }
      });
    }

    private static String toUpper(String name) {
      return name.isEmpty() ? name : Character.toUpperCase(name.charAt(0)) + name.substring(1);
    }
